        private static void Record(Frame f, bool outcome)
        {
            var key = ((ulong)(uint)f.Id << 33) | ((ulong)f.Evaluated << 17) | ((ulong)f.Values << 1) | (outcome ? 1ul : 0ul);
            _hits.TryAdd(key, 0);
